<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mdsrmodel extends CI_Model {    function fnGetDSRInfo($VarDSR = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,dsrname,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_DYEING_SPECIAL_REQUEST);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarDSR <> '') {            $ArrWhere['dsrname'] = trim($VarDSR);        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckDsr($VarDSR = '', $VarId = '') {        $this->db->from(KN_MASTER_DYEING_SPECIAL_REQUEST);        //$ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarDSR <> '') {            $ArrWhere['dsrname'] = trim($VarDSR);        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveDSRInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetDSRInfo($ArrUpdateData['dsrname'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_DYEING_SPECIAL_REQUEST, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This dyeing special request already exists";            }        } else {            $VarAlreadyExists = $this->fnCheckDsr($ArrUpdateData['dsrname'], $VarId);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_DYEING_SPECIAL_REQUEST, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This dyeing special request already exists";            }        }        return $ArrResult;    }    function fnCountDSR($VarDSR = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarDSR <> '') {            $ArrWhere[] = "dn.dsrname like '%" . $VarDSR . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "dn.dsrname like '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "dn.status=" . $VarStatus;        } else {            $ArrWhere[] = "dn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND dn.companyid = '" . $ArrUserLoggedInfo['companyid'] . "' ";        }        $VarSqlDSR = "SELECT count(1) as trec  FROM " . KN_MASTER_DYEING_SPECIAL_REQUEST . " AS dn LEFT JOIN " . KN_USERS . " AS u ON dn.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlDSR)->row();        return $ObjRows->trec;    }    function fnListDSR($VarDSR = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('dn.dsrname', 'dn.status', 'u.contactname', 'dn.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'dn.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarAfilter <> '') {            $ArrWhere[] = "dn.dsrname like '" . $VarAfilter . "%'";        }        if ($VarDSR <> '') {            $ArrWhere[] = "dn.dsrname like '%" . $VarDSR . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "dn.status=" . $VarStatus;        } else {            $ArrWhere[] = "dn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND dn.companyid = '" . $ArrUserLoggedInfo['companyid'] . "' ";        }        // removed this line  . " limit " . $VarLimitInfo in below query        $VarSqlDSR = "SELECT dn.id,dn.dsrname,u.contactname,dn.datecreated,dn.dateupdated,dn.status FROM " . KN_MASTER_DYEING_SPECIAL_REQUEST . " AS dn LEFT JOIN " . KN_USERS . " AS u ON dn.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlDSR);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_DYEING_SPECIAL_REQUEST, array('status' => $optvalue))) {            return true;        }        return false;    }    /************************************************************** Colour match standard from here type 2 **************************************************************/    function fnGetColourmsInfo($VarCms = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,colormatchstd,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_DYEING_SPECIAL_REQUEST);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarCms <> '') {            $ArrWhere['colormatchstd'] = $VarCms;        }        $ArrWhere['type'] = '2';        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckCms($VarCms = '', $VarId = '') {        $this->db->from(KN_MASTER_DYEING_SPECIAL_REQUEST);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarCms <> '') {            $ArrWhere['colormatchstd'] = $VarCms;        }        $ArrWhere['type'] = '2';        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveColourmsInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetColourmsInfo($ArrUpdateData['colormatchstd'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_DYEING_SPECIAL_REQUEST, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This color matching standard already exists";            }        } else {            $VarAlreadyExists = $this->fnCheckCms($ArrUpdateData['colormatchstd'], $VarId);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_DYEING_SPECIAL_REQUEST, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This color matching standard already exists";            }        }        return $ArrResult;    }    function fnCountColourms($VarDSR = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarDSR <> '') {            $ArrWhere[] = "c.colormatchstd like '%" . $VarDSR . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "c.colormatchstd like '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.companyid = " . $ArrUserLoggedInfo['companyid'] . " AND c.type='2' ";        }        $VarSqlDSR = "SELECT count(1) as trec  FROM " . KN_MASTER_DYEING_SPECIAL_REQUEST . " AS c LEFT JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlDSR)->row();        return $ObjRows->trec;    }    function fnListColourms($VarCms = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('c.colormatchstd', 'c.status', 'u.contactname', 'l.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'c.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarAfilter <> '') {            $ArrWhere[] = "c.colormatchstd like '" . $VarAfilter . "%'";        }        if ($VarCms <> '') {            $ArrWhere[] = "c.colormatchstd like '%" . $VarCms . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.type = '2' AND c.companyid = '" . $ArrUserLoggedInfo['companyid'] . "' ";        }        // removed this  . " limit " . $VarLimitInfo line in below query         $VarSqlDSR = "SELECT c.id,c.colormatchstd,u.contactname,c.datecreated,c.dateupdated,c.status FROM " . KN_MASTER_DYEING_SPECIAL_REQUEST . " AS c LEFT JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlDSR);        return $ObjResult;    }    function fnChangeColourms($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_DYEING_SPECIAL_REQUEST, array('status' => $optvalue))) {            return true;        }        return false;    }}